{"path": "/tmp/sv-904ee221b8cf4e6aba3cf924a8f1f63f/Components/Pages/Board/KanbanBoard.razor", "file_text": "@page "/board"
@using sv_904ee221b8cf4e6aba3cf924a8f1f63f
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Kanban Board</h1>

@if (isLoading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="filteredTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        @for (int i = 0; i < columns.Length; i++)
        {
            var colIndex = i;
            var column = columns[colIndex];
            var columnTasks = filteredTasks.Where(t => t.Status == column).ToList();

            <KanbanColumn Title="@column"
                          Status="@column"
                          Tasks="columnTasks"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < columns.Length - 1"
                          OnMoveTask="args => HandleMoveTask(args.Task, args.Direction, colIndex)"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> allTasks = new();
    private List<TaskItem> filteredTasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
            ApplyFilter();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string term)
    {
        searchTerm = term;
        ApplyFilter();
    }

    private void ApplyFilter()
    {
        filteredTasks = string.IsNullOrWhiteSpace(searchTerm)
            ? allTasks.ToList()
            : allTasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    private async Task HandleMoveTask(TaskItem task, string direction, int currentColIndex)
    {
        var targetIndex = direction == "left" ? currentColIndex - 1 : currentColIndex + 1;
        if (targetIndex < 0 || targetIndex >= columns.Length) return;

        var newStatus = columns[targetIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
            ApplyFilter();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(TaskItem formData)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            allTasks.Add(created);
            ApplyFilter();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}
"}

